const D = { energy: .62, density: .55, speed: 1, scale: 1, persist: .88, hue: 200, x: .5, y: .5, style: 'plasma', attractor: 'lorenz', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const BW = 200, BH = Math.max(80, Math.round(BW * height / width));
if (!S.g || S.bw !== BW || S.bh !== BH) {
  S.g = createGraphics(BW, BH); S.g.pixelDensity(1);
  S.dens = new Float32Array(BW * BH); S.chr = new Float32Array(BW * BH);
  S.bw = BW; S.bh = BH; S.px = 0.1; S.py = 0; S.pz = 0.05; S.warm = 0;
}
if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
  S.hoff = fr(1); S.pj = fr(2) * 2 - 1; S.px = 0.1 + fr(3) * 0.3; S.py = fr(4) * 0.2; S.pz = 0.05 + fr(5) * 0.2; S.warm = 0;
}

const g = S.g, dens = S.dens, chr = S.chr;
const styleI = P.style === 'thermal' ? 1 : P.style === 'sumi' ? 2 : P.style === 'blueprint' ? 3 : P.style === 'iridescent' ? 4 : 0;
let sys = P.attractor === 'rossler' ? 1 : P.attractor === 'thomas' ? 2 : 0;
if (S.sysUsed !== sys) { S.sysUsed = sys; S.px = 0.1; S.py = 0; S.pz = 0.05; S.warm = 0; }

// per-system integration constants: dt, center(cx,cy,cz), fit, speedRef
const SP = sys === 0 ? [0.0055, 0, 0, 25, 1 / 24, 240]
         : sys === 1 ? [0.022, 0, 0, 6, 1 / 13, 20]
         : [0.05, 0, 0, 0, 1 / 4.2, 5.5];
const dt = SP[0], cx = SP[1], cy = SP[2], cz = SP[3], fit = SP[4], ref = SP[5];
const sec = K.section;
// slow dramaturgical morph of the governing parameter -> the shape evolves over minutes
const rho = 28 + 3.0 * Math.sin(K.t * 0.021) + (sec - 3.5) * 0.9 + S.pj * 1.6;
const rc  = 5.7 + 0.35 * Math.sin(K.t * 0.019) + (sec - 3.5) * 0.06 + S.pj * 0.15;
const tb  = 0.2 + 0.01 * Math.sin(K.t * 0.03) + S.pj * 0.004;

// slow 3D rotation of the projection = the motion floor (continuous on K.t, never re-phases)
const rotRate = 0.09 + P.speed * 0.12;
const ay = K.t * rotRate + A.rms * 0.4 * Math.sin(K.t * 0.7);
const ax = 0.46 + 0.26 * Math.sin(K.t * 0.043);
const cay = Math.cos(ay), say = Math.sin(ay), cax = Math.cos(ax), sax = Math.sin(ax);
const view = Math.min(BW, BH) * 0.42 * P.scale;
const hbw = BW * 0.5, hbh = BH * 0.5;

// fade the density field (trail persistence)
const decay = 0.80 + P.persist * 0.185;
for (let i = 0, n = BW * BH; i < n; i++) { dens[i] *= decay; chr[i] *= decay; }

// integrate the ODE many steps/frame and splat into the fading buffer
let x = S.px, y = S.py, z = S.pz;
const steps = Math.round(900 + P.density * 3200);
for (let s = 0; s < steps; s++) {
  let dx, dy, dz;
  if (sys === 0) { dx = 10 * (y - x); dy = x * (rho - z) - y; dz = x * y - 2.667 * z; }
  else if (sys === 1) { dx = -y - z; dy = x + 0.2 * y; dz = 0.2 + z * (x - rc); }
  else { dx = Math.sin(y) - tb * x; dy = Math.sin(z) - tb * y; dz = Math.sin(x) - tb * z; }
  const spd = Math.sqrt(dx * dx + dy * dy + dz * dz);
  x += dx * dt; y += dy * dt; z += dz * dt;
  if (!(x > -1e5 && x < 1e5) || !(y > -1e5 && y < 1e5) || !(z > -1e5 && z < 1e5)) { x = 0.1; y = 0; z = 0.05; continue; }
  const nx = (x - cx) * fit, ny = (y - cy) * fit, nz = (z - cz) * fit;
  const rx = nx * cay - nz * say;
  const rz0 = nx * say + nz * cay;
  const ry = ny * cax - rz0 * sax;
  const rz = ny * sax + rz0 * cax;
  const bxi = (hbw + rx * view) | 0, byi = (hbh - ry * view) | 0;
  if (bxi >= 0 && bxi < BW && byi >= 0 && byi < BH) {
    const bi = byi * BW + bxi;
    dens[bi] += 1;
    chr[bi] += (spd / ref) * 0.55 + (rz * 0.5 + 0.55) * 0.45;
  }
}
S.px = x; S.py = y; S.pz = z;
if (S.warm < 6) { S.warm++; }

// iq cosine palette (rgb 0..1)
function pal(m) {
  return [0.5 + 0.5 * Math.cos(6.2831 * (m + 0.00)),
          0.5 + 0.5 * Math.cos(6.2831 * (m + 0.33)),
          0.5 + 0.5 * Math.cos(6.2831 * (m + 0.66))];
}
const hueBase = ((P.hue + S.hoff * 60 + sec * 12) % 360) / 360;
const expo = 0.6 + P.energy * 2.3 + K.intensity * 0.5 + A.bass * 1.5;
const cspan = 0.85;

g.loadPixels();
const px = g.pixels;
for (let j = 0; j < BH; j++) {
  const cyn = j / BH - 0.5;
  for (let i = 0; i < BW; i++) {
    const bi = j * BW + i;
    const d = dens[bi];
    const dn = 1 - Math.exp(-d * expo * 0.05);
    const avgc = d > 0.0001 ? chr[bi] / d : 0;
    const cxn = i / BW - 0.5;
    const vig = Math.exp(-(cxn * cxn + cyn * cyn) * 2.6);
    let r, gg, b;
    if (styleI === 1) { // thermal false-color
      const m = dn;
      r = Math.min(1, Math.max(0, m * 1.9 - 0.04));
      gg = Math.min(1, Math.max(0, m * 2.3 - 0.85));
      b = Math.min(1, Math.max(0, m * 3.4 - 2.3)) + Math.max(0, 0.42 - m * 1.6) * 0.55;
      const lift = 0.03 + 0.05 * vig;
      r = Math.min(1, r + lift * 0.5); gg = Math.min(1, gg + lift * 0.1); b = Math.min(1, b + lift);
    } else if (styleI === 2) { // sumi ink on warm paper
      const tex = 0.85 + 0.3 * (Math.sin(i * 12.9 + j * 78.2) * 43758.5 % 1);
      const ink = Math.pow(dn, 0.85) * tex;
      const tone = 1 - Math.min(1, ink) * 0.9;
      r = 0.94 * tone; gg = 0.905 * tone; b = 0.82 * tone;
    } else if (styleI === 3) { // blueprint schematic
      const grid = ((i % 22 === 0) || (j % 22 === 0)) ? 0.05 : 0;
      const line = Math.pow(dn, 0.55);
      r = 0.02 + grid * 0.4 + line * 0.14;
      gg = 0.05 + grid * 0.9 + line * 0.72;
      b = 0.15 + grid * 1.1 + line * 0.98;
      if (dn > 0.55) { const w = (dn - 0.55) * 1.4; r += w * 0.5; gg += w * 0.55; b += w * 0.4; }
    } else if (styleI === 4) { // iridescent oil-slick
      const hh = (avgc * 2.1 + dn * 0.6 + K.t * 0.03 + hueBase) % 1;
      const c = pal(hh); const sh = 0.28 + 0.72 * dn;
      const lift = 0.05 * vig;
      r = c[0] * sh + lift * 0.4; gg = c[1] * sh + lift * 0.4; b = c[2] * sh + lift * 0.6;
    } else { // plasma-ribbon (default): glowing color by speed/depth on a deep nebular ground
      const c = pal(avgc * cspan + hueBase);
      const bright = 0.9 + 0.55 * dn;
      const lift = 0.20 + 0.30 * vig;
      const gR = 0.40 * lift, gG = 0.18 * lift, gB = 0.66 * lift;
      r = Math.min(1, gR + c[0] * dn * bright);
      gg = Math.min(1, gG + c[1] * dn * bright);
      b = Math.min(1, gB + c[2] * dn * bright);
    }
    const o = 4 * bi;
    px[o] = r * 255; px[o + 1] = gg * 255; px[o + 2] = b * 255; px[o + 3] = 255;
  }
}
g.updatePixels();

push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();

// audio-reactive bloom on the bass — partial ADD tint, never full-frame flash (won't strobe)
if ((A.bass > 0.02 || A.treble > 0.02) && styleI !== 2) {
  push(); blendMode(ADD); noStroke();
  const glow = (A.bass * 0.5 + A.treble * 0.35) * (0.4 + P.energy * 0.6);
  fill((P.hue + 20) % 360, 45, 100, glow * 20);
  ellipse(P.x * width, P.y * height, width * 0.9, height * 0.9);
  blendMode(BLEND); pop();
}
